                            audio: 'ext:英雄传奇/audio:2',
                            enable: 'phaseUse',
                            usable: 1,
                            filterTarget(card, player, target) {
                                return target != player && target.countCards('h');
                            },
                            filter(event, player) {
                                return (
                                    player.countCards('h') > 0 &&
                                    game.hasPlayer(function (current) {
                                        return player != current && current.countCards('h') > 0;
                                    })
                                );
                            },
                            content() {
                                'step 0';
                                player
                                    .chooseControl('全部手牌', '等量手牌')
                                    .set('dialog', ['裂帛:请选择以下一项执行'])
                                    .set('ai', function () {
                                        if (get.attitude(player, target) > 0) {
                                            if (target.countCards('h') > player.countCards('h') && target.countCards('j') > 0) return '全部手牌';
                                            return '等量手牌';
                                        } else {
                                            if (target.countCards('h') > player.countCards('h')) return '全部手牌';
                                            return '全部手牌';
                                        }
                                    });
                                ('step 1');
                                if (result.control == '全部手牌') {
                                    player.swapHandcards(target);
                                } else {
                                    var dialog = ['请选择要交换的手牌', '<div class="text center">目标手牌</div>', [target.getCards('h'), 'blank'], '<div class="text center">自己手牌</div>', player.getCards('h')];
                                    var next = player.chooseButton(dialog, true);
                                    next.set('filterButton', function (button) {
                                        var ss = target.getCards('h');
                                        var hs = _status.event.player.getCards('h');
                                        var sn = 0;
                                        var hn = 0;
                                        var ub = ui.selected.buttons;
                                        for (var i = 0; i < ub.length; i++) {
                                            if (ss.includes(ub[i].link)) sn++;
                                            else hn++;
                                        }
                                        return !((sn >= hs.length && ss.includes(button.link)) || (hn >= ss.length && hs.includes(button.link)));
                                    });
                                    next.set('selectButton', function () {
                                        if (ui.selected.buttons.length == 0) return 2;
                                        var ss = target.getCards('h');
                                        var hs = _status.event.player.getCards('h');
                                        var sn = 0;
                                        var hn = 0;
                                        var ub = ui.selected.buttons;
                                        for (var i = 0; i < ub.length; i++) {
                                            if (ss.includes(ub[i].link)) sn++;
                                            else hn++;
                                        }
                                        if (sn != hn) return 2 * Math.max(sn, hn);
                                        else {
                                            if (sn == ss.length || hn == hs.length || sn == hs.length || hn == ss.length) return ub.length;
                                            return [ub.length, ub.length + 1];
                                        }
                                    });
                                    next.set('ai', function (button) {
                                        var ss = target.getCards('h');
                                        var hs = _status.event.player.getCards('h');
                                        var sn = 0;
                                        var hn = 0;
                                        var ub = ui.selected.buttons;
                                        for (var i = 0; i < ub.length; i++) {
                                            if (ss.includes(ub[i].link)) sn++;
                                            else hn++;
                                        }
                                        return ss.includes(button.link) && hs.includes(button.link);
                                    });
                                }
                                ('step 2');
                                if (result.bool) {
                                    var gains = [];
                                    var pushs = [];
                                    for (var i = 0; i < result.links.length; i++) {
                                        var card = result.links[i];
                                        if (target.getCards('h').includes(card)) gains.push(card);
                                        else pushs.push(card);
                                    }
                                    player.gain(gains, target, 'draw');
                                    target.gain(pushs, player, 'draw');
                                }
                            },
                            ai: {
                                order: 4,
                                result: {
                                    target(player, target) {
                                        if (get.attitude(player, target) > 0 && target.countCards('j') > 0) return 1;
                                        if (get.attitude(player, target) < 0 && target.countCards() - player.countCards() < 2) return 1;
                                        return -1;
                                    },
                                },
                            },
